mapper.select:
SELECT *
FROM approval_instance
WHERE corpid = #{corpid}
  AND instance_id = #{instanceId}
  AND del = 0

SELECT *
FROM approval_instance
WHERE corpid = #{corpid}
  AND request_id = #{requestId}
  AND del = 0

SELECT *
FROM approval_instance_task
WHERE instance_id = #{instanceId}
  AND del = 0

    AND node_no = #{nodeNo}

ORDER BY id

SELECT DISTINCT instance.*
FROM approval_instance instance

    INNER JOIN approval_instance_task task
        ON task.instance_id = instance.instance_id
        AND task.assignee_id = #{userId}
        AND task.status = 'PENDING'
        AND task.del = 0

WHERE instance.corpid = #{corpid}
  AND instance.del = 0


        AND instance.status IN ('PENDING_APPROVAL', 'IN_APPROVAL')


        AND instance.submitter_id = #{userId}


        AND instance.status IN ('APPROVED', 'REJECTED', 'WITHDRAWN')
        AND (
            instance.submitter_id = #{userId}
            OR EXISTS (
                SELECT 1
                FROM approval_instance_task completed_task
                WHERE completed_task.instance_id = instance.instance_id
                  AND completed_task.assignee_id = #{userId}
                  AND completed_task.del = 0
            )
        )



    AND instance.status = #{status}


    AND instance.business_code = #{businessCode}


    AND (instance.subject_summary LIKE CONCAT('%', #{keyword}, '%')
        OR instance.submitter_id LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY instance.submitted_at DESC, instance.id DESC

SELECT COUNT(1)
FROM approval_instance instance
WHERE instance.corpid = #{corpid}
  AND instance.instance_id = #{instanceId}
  AND instance.del = 0
  AND (
    instance.submitter_id = #{userId}
    OR EXISTS (
        SELECT 1
        FROM approval_instance_task task
        WHERE task.instance_id = instance.instance_id
          AND task.assignee_id = #{userId}
          AND task.del = 0
    )
  )

mapper.insert:
INSERT INTO approval_instance_task (
    instance_id, node_no, assignee_id, status, comment, handled_at, del, add_time, update_time
) VALUES (
    #{instanceId}, #{nodeNo}, #{assigneeId}, #{status}, #{comment}, #{handledAt},
    #{del}, #{addTime}, #{updateTime}
)

mapper.update:
UPDATE approval_instance_task
SET status = 'PENDING',
    update_time = #{activatedAt}
WHERE instance_id = #{instanceId}
  AND node_no = #{nodeNo}
  AND status = 'WAITING'
  AND del = 0

UPDATE approval_instance_task
SET status = 'CANCELLED',
    handled_at = #{handledAt},
    update_time = #{handledAt}
WHERE instance_id = #{instanceId}
  AND node_no = #{nodeNo}
  AND status = 'PENDING'
  AND del = 0

